/**
 * string-utils.mjs — small, dependency-free string helpers (HO-0007).
 *
 * Exports: truncate, pad, wrap
 */

/**
 * Truncate `text` to `maxLength` characters, appending `suffix` when the
 * input is longer than the limit. The result is never longer than
 * `maxLength`.
 *
 * @param {string} text input string
 * @param {number} maxLength maximum allowed length of the result
 * @param {string} [suffix='…'] marker appended when truncation occurs
 * @returns {string} truncated string
 */
export function truncate(text, maxLength, suffix = '…') {
  if (typeof maxLength !== 'number' || Number.isNaN(maxLength)) {
    throw new TypeError('maxLength must be a number');
  }
  if (maxLength < 0) maxLength = 0;
  if (typeof suffix !== 'string') suffix = String(suffix);
  if (text.length <= maxLength) return text;
  if (maxLength <= suffix.length) return suffix.slice(0, maxLength);
  return text.slice(0, maxLength - suffix.length) + suffix;
}

/**
 * Left-pad `text` with `char` so the result is exactly `length` characters
 * wide. Longer inputs are returned unchanged.
 *
 * @param {string} text input string
 * @param {number} length target width of the result
 * @param {string} [char=' '] padding character (only its first char is used)
 * @returns {string} padded string
 */
export function pad(text, length, char = ' ') {
  if (typeof length !== 'number' || Number.isNaN(length)) {
    throw new TypeError('length must be a number');
  }
  if (length <= text.length) return text;
  const padChar = char === '' ? ' ' : String(char)[0];
  const needed = length - text.length;
  return padChar.repeat(needed) + text;
}

/**
 * Greedy word-wrap: split `text` into lines no wider than `width`, breaking
 * at whitespace. Words longer than `width` occupy a line of their own.
 * Empty or whitespace-only input yields an empty array.
 *
 * @param {string} text input string
 * @param {number} width maximum line width
 * @returns {string[]} wrapped lines
 */
export function wrap(text, width) {
  if (typeof width !== 'number' || Number.isNaN(width)) {
    throw new TypeError('width must be a number');
  }
  if (width <= 0) return [];
  const words = String(text).split(/\s+/).filter(Boolean);
  const lines = [];
  let current = '';
  for (const word of words) {
    if (current === '') {
      current = word;
    } else if ((current + ' ' + word).length > width) {
      lines.push(current);
      current = word;
    } else {
      current += ' ' + word;
    }
  }
  if (current !== '') lines.push(current);
  return lines;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { truncate, pad, wrap } from '../src/string-utils.mjs';

// ---------- truncate ----------

test('truncate: keeps short strings unchanged', () => {
  assert.equal(truncate('hello', 10), 'hello');
});

test('truncate: leaves exact-length strings unchanged', () => {
  assert.equal(truncate('hello', 5), 'hello');
});

test('truncate: appends default suffix when text is too long', () => {
  assert.equal(truncate('hello world', 8), 'hello…');
});

test('truncate: honors a custom suffix', () => {
  assert.equal(truncate('hello world', 8, '...'), 'hello...');
  assert.equal(truncate('hello world', 9, '...'), 'hello w...');
});

test('truncate: no suffix when maxLength fits the suffix alone', () => {
  assert.equal(truncate('hello world', 1), '…');
  assert.equal(truncate('hello world', 2, '...'), '..');
});

test('truncate: zero length yields empty string', () => {
  assert.equal(truncate('hello', 0), '');
});

// ---------- pad ----------

test('pad: left-pads with spaces to reach target width', () => {
  assert.equal(pad('42', 5), '   42');
});

test('pad: longer-or-equal inputs are returned unchanged', () => {
  assert.equal(pad('hello', 3), 'hello');
  assert.equal(pad('hello', 5), 'hello');
});

test('pad: supports a custom padding character', () => {
  assert.equal(pad('7', 3, '0'), '007');
});

test('pad: empty char falls back to a space', () => {
  assert.equal(pad('x', 3, ''), '  x');
});

// ---------- wrap ----------

test('wrap: word-wraps text to the given width', () => {
  assert.deepEqual(
    wrap('The quick brown fox jumps over the lazy dog', 10),
    ['The quick', 'brown fox', 'jumps over', 'the lazy', 'dog'],
  );
});

test('wrap: single line fits entirely', () => {
  assert.deepEqual(wrap('short line', 20), ['short line']);
});

test('wrap: empty and whitespace-only input yields no lines', () => {
  assert.deepEqual(wrap('', 10), []);
  assert.deepEqual(wrap('   \t  ', 10), []);
});

test('wrap: an oversized word occupies its own line', () => {
  assert.deepEqual(wrap('supercalifragilistic', 5), ['supercalifragilistic']);
});

test('wrap: width of zero or less yields no lines', () => {
  assert.deepEqual(wrap('hello world', 0), []);
  assert.deepEqual(wrap('hello world', -1), []);
});

