import { test } from 'node:test';
import assert from 'node:assert/strict';
import { truncate, pad, wrap } from '../src/string-utils.mjs';

// ---------- truncate ----------

test('truncate: keeps short strings unchanged', () => {
  assert.equal(truncate('hello', 10), 'hello');
});

test('truncate: leaves exact-length strings unchanged', () => {
  assert.equal(truncate('hello', 5), 'hello');
});

test('truncate: appends default suffix when text is too long', () => {
  assert.equal(truncate('hello world', 8), 'hello…');
});

test('truncate: honors a custom suffix', () => {
  assert.equal(truncate('hello world', 8, '...'), 'hello...');
  assert.equal(truncate('hello world', 9, '...'), 'hello w...');
});

test('truncate: no suffix when maxLength fits the suffix alone', () => {
  assert.equal(truncate('hello world', 1), '…');
  assert.equal(truncate('hello world', 2, '...'), '..');
});

test('truncate: zero length yields empty string', () => {
  assert.equal(truncate('hello', 0), '');
});

// ---------- pad ----------

test('pad: left-pads with spaces to reach target width', () => {
  assert.equal(pad('42', 5), '   42');
});

test('pad: longer-or-equal inputs are returned unchanged', () => {
  assert.equal(pad('hello', 3), 'hello');
  assert.equal(pad('hello', 5), 'hello');
});

test('pad: supports a custom padding character', () => {
  assert.equal(pad('7', 3, '0'), '007');
});

test('pad: empty char falls back to a space', () => {
  assert.equal(pad('x', 3, ''), '  x');
});

// ---------- wrap ----------

test('wrap: word-wraps text to the given width', () => {
  assert.deepEqual(
    wrap('The quick brown fox jumps over the lazy dog', 10),
    ['The quick', 'brown fox', 'jumps over', 'the lazy', 'dog'],
  );
});

test('wrap: single line fits entirely', () => {
  assert.deepEqual(wrap('short line', 20), ['short line']);
});

test('wrap: empty and whitespace-only input yields no lines', () => {
  assert.deepEqual(wrap('', 10), []);
  assert.deepEqual(wrap('   \t  ', 10), []);
});

test('wrap: an oversized word occupies its own line', () => {
  assert.deepEqual(wrap('supercalifragilistic', 5), ['supercalifragilistic']);
});

test('wrap: width of zero or less yields no lines', () => {
  assert.deepEqual(wrap('hello world', 0), []);
  assert.deepEqual(wrap('hello world', -1), []);
});

