/**
 * string-utils.mjs — small, dependency-free string helpers (HO-0007).
 *
 * Exports: truncate, pad, wrap
 */

/**
 * Truncate `text` to `maxLength` characters, appending `suffix` when the
 * input is longer than the limit. The result is never longer than
 * `maxLength`.
 *
 * @param {string} text input string
 * @param {number} maxLength maximum allowed length of the result
 * @param {string} [suffix='…'] marker appended when truncation occurs
 * @returns {string} truncated string
 */
export function truncate(text, maxLength, suffix = '…') {
  if (typeof maxLength !== 'number' || Number.isNaN(maxLength)) {
    throw new TypeError('maxLength must be a number');
  }
  if (maxLength < 0) maxLength = 0;
  if (typeof suffix !== 'string') suffix = String(suffix);
  if (text.length <= maxLength) return text;
  if (maxLength <= suffix.length) return suffix.slice(0, maxLength);
  return text.slice(0, maxLength - suffix.length) + suffix;
}

/**
 * Left-pad `text` with `char` so the result is exactly `length` characters
 * wide. Longer inputs are returned unchanged.
 *
 * @param {string} text input string
 * @param {number} length target width of the result
 * @param {string} [char=' '] padding character (only its first char is used)
 * @returns {string} padded string
 */
export function pad(text, length, char = ' ') {
  if (typeof length !== 'number' || Number.isNaN(length)) {
    throw new TypeError('length must be a number');
  }
  if (length <= text.length) return text;
  const padChar = char === '' ? ' ' : String(char)[0];
  const needed = length - text.length;
  return padChar.repeat(needed) + text;
}

/**
 * Greedy word-wrap: split `text` into lines no wider than `width`, breaking
 * at whitespace. Words longer than `width` occupy a line of their own.
 * Empty or whitespace-only input yields an empty array.
 *
 * @param {string} text input string
 * @param {number} width maximum line width
 * @returns {string[]} wrapped lines
 */
export function wrap(text, width) {
  if (typeof width !== 'number' || Number.isNaN(width)) {
    throw new TypeError('width must be a number');
  }
  if (width <= 0) return [];
  const words = String(text).split(/\s+/).filter(Boolean);
  const lines = [];
  let current = '';
  for (const word of words) {
    if (current === '') {
      current = word;
    } else if ((current + ' ' + word).length > width) {
      lines.push(current);
      current = word;
    } else {
      current += ' ' + word;
    }
  }
  if (current !== '') lines.push(current);
  return lines;
}
